def is_palindrome(s):
    cleaned = ""
    for ch in s:
        if ch.isalnum():
            cleaned += ch.lower()
    return cleaned == cleaned[::-1]

if __name__ == "__main__":
    test_words = ["Race car", "madam", "hello"]
    for word in test_words:
        print("YES" if is_palindrome(word) else "NO")

